/// The gallery's example of `Ticker`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_speed = args.number("speed") as f32;
        let arg_gap = args.number("gap") as f32;
        let arg_reverse = args.bool("reverse");

        let chips = HStack::new((
            Badge::new("Button").tone(Tone::Accent),
            Badge::new("DataGrid"),
            Badge::new("Scheduler").tone(Tone::Success),
            Badge::new("Ribbon"),
            Badge::new("Chart").tone(Tone::Warning),
            Badge::new("CommandPalette"),
        ))
        .spacing(12.0);
        VStack::new(({
            let mut it = Ticker::new(chips);
            it = it.speed(arg_speed);
            it = it.gap(arg_gap);
            if arg_reverse {
                it = it.reverse();
            }
            it
        },))
        .padding(8.0)
    })
}

impl ComponentBook for Ticker<AnyView> {
    fn book() -> Meta {
        Meta::new("Layout/Ticker", render)
            .summary("A strip of content that keeps moving sideways, still under reduced motion.")
            .arg(ArgType::number("speed", 40.0, 0.0, 160.0, 1.0))
            .arg(ArgType::number("gap", 12.0, 0.0, 48.0, 0.1))
            .arg(ArgType::bool("reverse", false))
            .story("Example", Args::new())
    }
}
